 function finishRound(points,why){score+=points;correct++;locked=true;var nxt=index+1,done=nxt>=rounds.length;feedback('✓ '+esc(why||'চমৎকার! ধারণাটি ঠিক ধরেছ।')+(done?'':' <button type="button" class="aq-next" data-aq-next>পরের মিশন →</button>'),true);if(done){root.querySelector('.aq-play').insertAdjacentHTML('beforeend','<div class="aq-finish"><span>MISSION CLEAR</span><b>'+score+' PTS</b><p>'+correct+' / '+rounds.length+'টি মিশন সম্পন্ন</p><button type="button" class="btn pri" data-aq-finish>ফলাফল দেখুন →</button></div>');root.querySelector('[data-aq-finish]').onclick=function(){A.done({score:score,pct:correct/rounds.length,detail:correct+' / '+rounds.length+' missions completed'});};} }
